return ['domain'=>'beltoft-pos','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'pt_PT','project-id-version'=>'Beltoft POS 0.1.0','pot-creation-date'=>'2026-10-14T10:38:04+00:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['Beltoft POS'=>'Beltoft POS','Point of sale for the shop counter: its own host, login, product list and checkout.'=>'Ponto de venda para o balcão da loja: o seu próprio domínio, início de sessão, lista de produtos e checkout.','beltoft.net'=>'beltoft.net','Till not set up.'=>'Caixa não configurada.','The till has no page yet. Publish the POS page and set its ID in the option beltoft_pos_page_id.'=>'A caixa ainda não tem página. Publique a página da caixa e defina o seu ID na opção beltoft_pos_page_id.','Records how a counter sale was paid. No payment is processed.'=>'Regista como foi paga uma venda ao balcão. Nenhum pagamento é processado.','This payment method is only available at the till.'=>'Este método de pagamento só está disponível na caixa.','Counter sale paid: %s'=>'Venda ao balcão paga: %s','MB WAY'=>'MB WAY','Card (Teya)'=>'Cartão (Teya)','Cash'=>'Dinheiro','Bank transfer'=>'Transferência bancária','Please sign in to the till.'=>'Inicie sessão na caixa.','This account has no access to the till.'=>'Esta conta não tem acesso à caixa.','Beltoft POS needs WooCommerce.'=>'O Beltoft POS precisa do WooCommerce.','Receipt sent to %s.'=>'Recibo enviado para %s.','This order is not a till sale.'=>'Esta encomenda não é uma venda da caixa.','Enter a valid email address.'=>'Introduza um endereço de email válido.','Receipt emailed to %s.'=>'Recibo enviado por email para %s.','The receipt could not be sent.'=>'Não foi possível enviar o recibo.','Till stock'=>'Stock da caixa','Counted separately from the shop stock above. Leave empty if it has never been counted. The till never refuses a sale over this count, so it can go below zero.'=>'Contado à parte do stock da loja acima. Deixe vazio se nunca foi contado. A caixa nunca recusa uma venda por causa desta contagem, por isso pode ficar abaixo de zero.','%d product has sold past its counted till stock. The sales went through; the count needs correcting.'=>'%d produto vendeu mais do que o stock contado da caixa. As vendas foram feitas; a contagem tem de ser corrigida.' . "\0" . '%d produtos venderam mais do que o stock contado da caixa. As vendas foram feitas; as contagens têm de ser corrigidas.','Show them'=>'Mostrar','Till operator'=>'Operador de caixa','Walk-in customer'=>'Cliente de balcão','The till has no header: publish a Bricks header template with the slug %s (no conditions).'=>'A caixa não tem cabeçalho: publique um template de cabeçalho do Bricks com o slug %s (sem condições).','Quantity'=>'Quantidade','Decrease quantity'=>'Diminuir quantidade','Increase quantity'=>'Aumentar quantidade','Sold out'=>'Esgotado','Only %d in stock.'=>'Apenas %d em stock.','Could not add. Only %d in stock.'=>'Não foi possível adicionar. Apenas %d em stock.','Could not add this line.'=>'Não foi possível adicionar esta linha.','Till printing is on (1/0)'=>'Impressão na caixa ligada (1/0)','Till stock of item #%1$s: %2$s → %3$s.'=>'Stock da caixa do artigo #%1$s: %2$s → %3$s.','Beltoft POS is not reachable: set the till\'s hostname with <code>define( \'BELTOFT_POS_HOST\', \'pos.example.com\' );</code> in wp-config.php.'=>'O Beltoft POS não está acessível: defina o endereço da caixa com <code>define( \'BELTOFT_POS_HOST\', \'pos.example.com\' );</code> no wp-config.php.','This receipt belongs to another operator\'s sale.'=>'Este recibo pertence a uma venda de outro operador.','The till is not set up yet: its login page is missing.'=>'A caixa ainda não está configurada: falta a página de entrada.','This account can only sign in at the till.'=>'Esta conta só pode iniciar sessão na caixa.']];